7	import { type FunctionCall } from '@google/genai';
8	import { type ApprovalMode } from '../policy/types.js';
9	import type {
10	  ToolConfirmationOutcome,
11	  ToolConfirmationPayload,
12	  DiffStat,
13	} from '../tools/tools.js';
14	import type { ToolCall } from '../scheduler/types.js';
15	import type { SandboxPermissions } from '../services/sandboxManager.js';
16	import type { SubagentActivityItem } from '../agents/types.js';
17	
18	export enum MessageBusType {
19	  TOOL_CONFIRMATION_REQUEST = 'tool-confirmation-request',
20	  TOOL_CONFIRMATION_RESPONSE = 'tool-confirmation-response',
21	  TOOL_POLICY_REJECTION = 'tool-policy-rejection',
22	  TOOL_EXECUTION_SUCCESS = 'tool-execution-success',
23	  TOOL_EXECUTION_FAILURE = 'tool-execution-failure',
24	  UPDATE_POLICY = 'update-policy',
25	  TOOL_CALLS_UPDATE = 'tool-calls-update',
26	  ASK_USER_REQUEST = 'ask-user-request',
27	  ASK_USER_RESPONSE = 'ask-user-response',
28	  SUBAGENT_ACTIVITY = 'subagent-activity',
29	}
30	
31	export interface ToolCallsUpdateMessage {
32	  type: MessageBusType.TOOL_CALLS_UPDATE;
33	  toolCalls: ToolCall[];
34	  schedulerId: string;
35	}
36	
37	export interface ToolConfirmationRequest {
38	  type: MessageBusType.TOOL_CONFIRMATION_REQUEST;
39	  toolCall: FunctionCall;
40	  correlationId: string;
41	  serverName?: string;
42	  /**
43	   * Optional tool annotations (e.g., readOnlyHint, destructiveHint) from MCP.
44	   */
45	  toolAnnotations?: Record<string, unknown>;
46	  /**
47	   * Optional subagent name, if this tool call was initiated by a subagent.
48	   */
49	  subagent?: string;
50	  /**
51	   * Optional rich details for the confirmation UI (diffs, counts, etc.)
52	   */
53	  details?: SerializableConfirmationDetails;
54	  /**
55	   * Optional decision to force for this tool call, bypassing the policy engine.
56	   */
57	  forcedDecision?: 'allow' | 'deny' | 'ask_user';
58	}
59	
60	export interface ToolConfirmationResponse {
61	  type: MessageBusType.TOOL_CONFIRMATION_RESPONSE;
62	  correlationId: string;
63	  confirmed: boolean;
64	  /**
65	   * The specific outcome selected by the user.
66	   *
67	   * TODO: Make required after migration.
68	   */
69	  outcome?: ToolConfirmationOutcome;
70	  /**
71	   * Optional payload (e.g., modified content for 'modify_with_editor').
72	   */
73	  payload?: ToolConfirmationPayload;
74	  /**
75	   * When true, indicates that policy decision was ASK_USER and the tool should
76	   * show its legacy confirmation UI instead of auto-proceeding.
77	   */
78	  requiresUserConfirmation?: boolean;
79	}
80	
81	/**
82	 * Data-only versions of ToolCallConfirmationDetails for bus transmission.
83	 */
84	export type SerializableConfirmationDetails =
85	  | {
86	      type: 'sandbox_expansion';
87	      title: string;
88	      command: string;
89	      rootCommand: string;
90	      additionalPermissions: SandboxPermissions;
91	      systemMessage?: string;
92	    }
93	  | {
94	      type: 'info';
95	      title: string;
96	      systemMessage?: string;
97	      prompt: string;
98	      urls?: string[];
99	    }
100	  | {
101	      type: 'edit';
102	      title: string;
103	      systemMessage?: string;
104	      fileName: string;
105	      filePath: string;
106	      fileDiff: string;
107	      originalContent: string | null;
108	      newContent: string;
109	      isModifying?: boolean;
110	      diffStat?: DiffStat;
111	    }
112	  | {
113	      type: 'exec';
114	      title: string;
115	      systemMessage?: string;
116	      command: string;
117	      rootCommand: string;
118	      rootCommands: string[];
119	      commands?: string[];
120	    }
121	  | {
122	      type: 'mcp';
123	      title: string;
124	      systemMessage?: string;
125	      serverName: string;
126	      toolName: string;
127	      toolDisplayName: string;
128	      toolArgs?: Record<string, unknown>;
129	      toolDescription?: string;
130	      toolParameterSchema?: unknown;
131	    }
132	  | {
133	      type: 'ask_user';
134	      title: string;
135	      systemMessage?: string;
136	      questions: Question[];
137	    }
138	  | {
139	      type: 'exit_plan_mode';
140	      title: string;
141	      systemMessage?: string;
142	      planPath: string;
143	    };
144	
145	export interface UpdatePolicy {
146	  type: MessageBusType.UPDATE_POLICY;
147	  toolName: string;
148	  persist?: boolean;
149	  persistScope?: 'workspace' | 'user';
150	  argsPattern?: string;
151	  commandPrefix?: string | string[];
152	  mcpName?: string;
153	  allowRedirection?: boolean;
154	  modes?: ApprovalMode[];
155	}
156	
157	export interface ToolPolicyRejection {
158	  type: MessageBusType.TOOL_POLICY_REJECTION;
159	  toolCall: FunctionCall;
160	}
161	
162	export interface ToolExecutionSuccess<T = unknown> {
163	  type: MessageBusType.TOOL_EXECUTION_SUCCESS;
164	  toolCall: FunctionCall;
165	  result: T;
166	}
167	
168	export interface ToolExecutionFailure<E = Error> {
169	  type: MessageBusType.TOOL_EXECUTION_FAILURE;
170	  toolCall: FunctionCall;
171	  error: E;
172	}
173	
174	export interface QuestionOption {
175	  label: string;
176	  description: string;
177	}
178	
179	export enum QuestionType {
180	  CHOICE = 'choice',
181	  TEXT = 'text',
182	  YESNO = 'yesno',
183	}
184	
185	export interface Question {
186	  question: string;
187	  header: string;
188	  /** Question type: 'choice' renders selectable options, 'text' renders free-form input, 'yesno' renders a Yes/No choice with an optional 'Other' feedback field. */
189	  type: QuestionType;
190	  /** Selectable choices. REQUIRED when type='choice'. IGNORED for 'text' and 'yesno'. */
191	  options?: QuestionOption[];
192	  /** Allow multiple selections. Only applies when type='choice'. */
193	  multiSelect?: boolean;
194	  /** Placeholder hint text. For type='text', shown in the input field. For type='choice' and 'yesno', shown in the 'Other' custom input. */
195	  placeholder?: string;
196	  /** Allow the question to consume more vertical space instead of being strictly capped. */
197	  unconstrainedHeight?: boolean;
198	}
199	
200	export interface AskUserRequest {
201	  type: MessageBusType.ASK_USER_REQUEST;
202	  questions: Question[];
203	  correlationId: string;
204	}
205	
206	export interface AskUserResponse {
207	  type: MessageBusType.ASK_USER_RESPONSE;
208	  correlationId: string;
209	  answers: { [questionIndex: string]: string };
210	  /** When true, indicates the user cancelled the dialog without submitting answers */
211	  cancelled?: boolean;
212	}
213	
214	export interface SubagentActivityMessage {
215	  type: MessageBusType.SUBAGENT_ACTIVITY;
216	  subagentName: string;
217	  activity: SubagentActivityItem;
218	}
219	
220	export type Message =
221	  | ToolConfirmationRequest
222	  | ToolConfirmationResponse
223	  | ToolPolicyRejection
224	  | ToolExecutionSuccess
225	  | ToolExecutionFailure
226	  | UpdatePolicy
227	  | AskUserRequest
228	  | AskUserResponse
229	  | ToolCallsUpdateMessage
230	  | SubagentActivityMessage;
