70	class TestTool extends BaseDeclarativeTool<TestParams, TestResult> {
71	  constructor(messageBus: MessageBus) {
72	    super(
73	      'test-tool',
74	      'Test Tool',
75	      'A test tool for message bus integration',
76	      Kind.Other,
77	      {
78	        type: 'object',
79	        properties: {
80	          testParam: { type: 'string' },
81	        },
82	        required: ['testParam'],
83	      },
84	      messageBus,
85	      true,
86	      false,
87	    );
88	  }
89	
90	  protected createInvocation(
91	    params: TestParams,
92	    messageBus: MessageBus,
93	    _toolName?: string,
94	    _toolDisplayName?: string,
95	  ) {
96	    return new TestToolInvocation(
97	      params,
98	      messageBus,
99	      _toolName,
100	      _toolDisplayName,
101	    );
102	  }
103	}
104	
105	describe('Message Bus Integration', () => {
106	  let policyEngine: PolicyEngine;
107	  let messageBus: MessageBus;
108	  let mockUUID: Mock;
109	
110	  beforeEach(() => {
