141	          name: 'test-tool',
142	          args: { testParam: 'test-value' },
143	        },
144	        correlationId: 'test-correlation-id',
145	      });
146	
147	      // Verify subscription to response
148	      expect(subscribeSpy).toHaveBeenCalledWith(
149	        MessageBusType.TOOL_CONFIRMATION_RESPONSE,
150	        expect.any(Function),
151	      );
152	
153	      // Simulate confirmation response
154	      const responseHandler = subscribeSpy.mock.calls[0][1];
155	      const response: ToolConfirmationResponse = {
156	        type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
157	        correlationId: 'test-correlation-id',
158	        confirmed: true,
159	      };
160	
161	      responseHandler(response);
162	
163	      const result = await confirmationPromise;
164	      expect(result).toBe(false); // No further confirmation needed
165	      expect(unsubscribeSpy).toHaveBeenCalled();
166	    });
167	
168	    it('should reject promise when confirmation is denied', async () => {
169	      const tool = new TestTool(messageBus);
170	      const invocation = tool.build({ testParam: 'test-value' });
171	
172	      const subscribeSpy = vi.spyOn(messageBus, 'subscribe');
173	
174	      const confirmationPromise = invocation.shouldConfirmExecute(
175	        new AbortController().signal,
176	      );
177	
178	      // Simulate denial response
179	      const responseHandler = subscribeSpy.mock.calls[0][1];
180	      const response: ToolConfirmationResponse = {
181	        type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
182	        correlationId: 'test-correlation-id',
183	        confirmed: false,
184	      };
185	
186	      responseHandler(response);
187	
188	      // Should reject with error when denied
