193	
194	    it('should handle timeout', async () => {
195	      vi.useFakeTimers();
196	
197	      const tool = new TestTool(messageBus);
198	      const invocation = tool.build({ testParam: 'test-value' });
199	
200	      const confirmationPromise = invocation.shouldConfirmExecute(
201	        new AbortController().signal,
202	      );
203	
204	      // Fast-forward past timeout
205	      vi.advanceTimersByTime(30000);
206	
207	      const result = await confirmationPromise;
208	      expect(result).toBe(false);
209	
210	      vi.useRealTimers();
211	    });
212	
213	    it('should handle abort signal', async () => {
214	      const tool = new TestTool(messageBus);
215	      const invocation = tool.build({ testParam: 'test-value' });
216	
217	      const abortController = new AbortController();
218	      const confirmationPromise = invocation.shouldConfirmExecute(
