229	
230	    it('should ignore responses with wrong correlation ID', async () => {
231	      vi.useFakeTimers();
232	
233	      const tool = new TestTool(messageBus);
234	      const invocation = tool.build({ testParam: 'test-value' });
235	
236	      const subscribeSpy = vi.spyOn(messageBus, 'subscribe');
237	      const confirmationPromise = invocation.shouldConfirmExecute(
238	        new AbortController().signal,
239	      );
240	
241	      // Send response with wrong correlation ID
242	      const responseHandler = subscribeSpy.mock.calls[0][1];
